    "html": "<table><thead><tr><td><b>Category</b></td><td><b>Core Task</b></td><td><b>Representative Methods</b></td><td><b>Strengths</b></td><td><b>Limitations</b></td></tr></thead><tbody><tr><td><span class='cell'>Semantic<br>Segmentation</span></td><td><span class='cell'>Pixel-/point-level<br>label prediction</span></td><td><span class='cell'>PointNet++ <br> KPConv <br> StratifiedTF <br> PointNeXt <br> PTv3 <br> Swin3D </span></td><td><span class='cell'><span class='pos'>•</span> + Establishes dense semantic basis<br> <span class='pos'>•</span> + Hierarchical & local feature learning<br> <span class='pos'>•</span> + Backbone for downstream tasks</span></td><td><span class='cell'> -- No instance distinction<br> -- Limited relational understanding<br> -- Closed-set categories</span></td></tr><tr><td>[2pt] <span class='cell'>Instance/ Panoptic<br>Segmentation</span></td><td><span class='cell'>Object-level<br>mask prediction</span></td><td><span class='cell'>3D-BoNet <br> HAIS <br> SoftGroup <br> Mask3D <br> OneFormer3D <br> Pano3D </span></td><td><span class='cell'><span class='pos'>•</span> + Object-aware reasoning<br> <span class='pos'>•</span> + Unified \"things\" & \"stuff\" modeling<br> <span class='pos'>•</span> + End-to-end mask prediction</span></td><td><span class='cell'> -- Occlusion handling<br> -- Over-segmentation<br> -- Post-processing still needed</span></td></tr><tr><td>[2pt] <span class='cell'>3D Object<br>Detection</span></td><td><span class='cell'>Bounding-box<br>localization</span></td><td><span class='cell'>VoteNet <br> FCAF3D <br> CAGroup3D <br> TR3D <br> SPGroup3D <br> Cubify Anything </span></td><td><span class='cell'><span class='pos'>•</span> + Compact representation<br> <span class='pos'>•</span> + Query-driven<br> <span class='pos'>•</span> + RGB-D multimodal fusion</span></td><td><span class='cell'> -- Coarse geometry<br> -- Bbox not sufficient for interaction<br> -- Small-object recall</span></td></tr><tr><td>[2pt] <span class='cell'>Scene Graph<br>Generation</span></td><td><span class='cell'>Relational<br>structure learning</span></td><td><span class='cell'>Neural Motifs <br> SceneGraphFusion <br> SGFormer <br> SDSGG <br> SceneLLM </span></td><td><span class='cell'><span class='pos'>•</span> + Relational reasoning<br> <span class='pos'>•</span> + Hierarchical scene modeling<br> <span class='pos'>•</span> + Embodied planning support</span></td><td><span class='cell'> -- Long-tail relations<br> -- Scalability issues<br> -- Noisy in cluttered scenes</span></td></tr><tr><td>[2pt] <span class='cell'>Layout<br>Estimation</span></td><td><span class='cell'>Room structure<br>recovery</span></td><td><span class='cell'>HorizonNet <br> LED2-Net <br> Bi-Layout <br> uLayout <br> Plane-DUSt3R </span></td><td><span class='cell'><span class='pos'>•</span> + Structural prior<br> <span class='pos'>•</span> + Topological reasoning<br> <span class='pos'>•</span> + Supports navigation and planning</span></td><td><span class='cell'> -- Manhattan-world assumption<br> -- Cluttered-scene fragmentation<br> -- Limited to rooms</span></td></tr><tr><td>[2pt] <span class='cell'>3D Visual<br>Grounding</span></td><td><span class='cell'>Language-grounded<br>object localization</span></td><td><span class='cell'>ScanRefer <br> InstanceRefer <br> 3DVG-Transformer <br> LanguageRefer <br> 3D-VisTA <br> LL3DA </span></td><td><span class='cell'><span class='pos'>•</span> + Open-ended queries<br> <span class='pos'>•</span> + Spatial-language alignment<br> <span class='pos'>•</span> + Embodied instruction interface</span></td><td><span class='cell'> -- Referring-expression ambiguity<br> -- Reliance on reconstruction quality<br> -- Annotation cost</span></td></tr><tr><td>[2pt] <span class='cell'>Semantic Geometry<br>Reconstruction</span></td><td><span class='cell'>Geometry-semantics<br>joint modeling</span></td><td><span class='cell'>OccNet <br> MonoScene <br> OpenOcc <br> SurroundOcc <br> Occ3D <br> VoxDet </span></td><td><span class='cell'><span class='pos'>•</span> + Continuous field rep.<br> <span class='pos'>•</span> + Navigable space<br> <span class='pos'>•</span> + Multi-task unified framework</span></td><td><span class='cell'> -- High memory cost<br> -- Sparse supervision<br> -- Resolution trade-off</span></td></tr></tbody></table>"
